UPDATE 일마감관리 SET
	수주최종번호 = #{chgNum}
WHERE 사업장 = #{bplcCode}
AND 마감일자 = CONVERT(VARCHAR,GETDATE(),112)

mapper.insert:

	 SELECT MAX(일련번호) AS EX_NO FROM 웹엑셀파일

INSERT INTO  웹엑셀파일
	(
		일련번호
		, 파일등록일자
		, 원본파일명
		, 서버파일명
		, 서버파일경로
		, 등록자
		, 등록일자
		, 등록시간
		, 수정자
		, 수정일자
		, 수정시간
	)
	VALUES(
		(SELECT ISNULL(MAX(일련번호+1),1) FROM 웹엑셀파일)
		, #{ordDe}
		, #{EXCEL_FILE_NM}
		, #{FILE_REAL_NM}
		, #{FILE_ABS_PT}
		, #{bcncCode}
		, CONVERT(VARCHAR,GETDATE(),112)
		, REPLACE(CONVERT(VARCHAR,GETDATE(),108),':','')
		, #{bcncCode}
		, CONVERT(VARCHAR,GETDATE(),112)
		, REPLACE(CONVERT(VARCHAR,GETDATE(),108),':','')
	);
